-- Rollback: UPDATE remediation_contracts SET verify_probe = (SELECT b.verify_probe FROM bak_20261028_cfa3_contracts b WHERE b.class = remediation_contracts.class), verify_transport = (SELECT b.verify_transport FROM bak_20261028_cfa3_contracts b WHERE b.class = remediation_contracts.class), last_verdict = (SELECT b.last_verdict FROM bak_20261028_cfa3_contracts b WHERE b.class = remediation_contracts.class), next_due_at = (SELECT b.next_due_at FROM bak_20261028_cfa3_contracts b WHERE b.class = remediation_contracts.class) WHERE class IN (SELECT class FROM bak_20261028_cfa3_contracts); UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261028_cfa3_issues b WHERE b.id = agent_issues.id) WHERE id IN (SELECT id FROM bak_20261028_cfa3_issues); UPDATE issue_triage SET triage_state = 'triaged', close_evidence = NULL WHERE owner = 'cluster-f-a' AND issue_id = 1000599; UPDATE agent_issues SET status = 'open', close_channel = NULL WHERE id = 1000599 AND close_channel = 'session:cluster-f-a'
-- BACKUP: bak_20261028_cfa3_contracts
--
-- CLUSTER-F-A part 3 (2026-10-28, charter pillar autonomy; agent_issues 1000599, 1000597, 100166 and the state notes of the issues that stay open).
--  1000597 (YT-6): its closing probe was the marker "averageViewDuration" in qnfo-youtube-shorts/worker.js, which the merged change (PR 5174, 0.3.0) satisfies although no viewer data exists yet: the first
--    tick after the deploy (2026-10-28T21:00:42Z) recorded youtube.retention_scope, the OAuth grant lacks youtube.readonly and yt-analytics.readonly. The contract now reads the definition of done: the metric
--    youtube_avg_view_duration_s holds a measured value. It fails until the owner gives the consent (human_actions yt-analytics-consent, IDENTITY-BOUND) and closes by itself after.
--  1000599: the merge-runner refusal for the YT-6 task is answered by the session pull request 5174, deployed (0.3.0-retention answers /health) and exercised by the 21:00Z tick.
--  100166: the in-account twin of the census check is one line in qnfo-fleet-control/worker.js (jCensusAndRegistry counts a retired row as blind); the file is under the code loop's live claim, so the change is handed to
--    the code loop as a code task (the runner side was fixed by PR 5176).
CREATE TABLE IF NOT EXISTS bak_20261028_cfa3_contracts AS SELECT class, verify_probe, verify_transport, last_verdict, next_due_at FROM remediation_contracts WHERE class = 'issue-1000597';
CREATE TABLE IF NOT EXISTS bak_20261028_cfa3_issues AS SELECT id, description FROM agent_issues WHERE id IN (100166, 1000301, 1000302, 1000303, 1000309, 1000310, 1000558, 1000629, 1000489, 1000630, 1000734, 1000610, 1000573, 1000571, 1000681, 1000682, 1000683, 1000678);

UPDATE remediation_contracts SET
  verify_probe = 'SELECT ''measured'' AS expected, CASE WHEN COALESCE((SELECT state FROM metric_registry WHERE metric = ''youtube_avg_view_duration_s''), '''') = ''MEASURED'' AND COALESCE((SELECT trim(last_value) FROM metric_registry WHERE metric = ''youtube_avg_view_duration_s''), '''') <> '''' THEN ''measured'' ELSE ''unmeasured: the read is refused until the owner consent yt-analytics-consent'' END AS observed',
  verify_transport = 'd1-query', last_verdict = NULL, next_due_at = datetime('now')
WHERE class = 'issue-1000597' AND verify_transport = 'code-read' AND instr(verify_probe, 'averageViewDuration') > 0;

INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence)
SELECT a.id, 'cluster-f-a', 'closed', 'cluster-f-a', datetime('now'),
  'CLUSTER-F-A 2026-10-28: the merge runner refused the code-loop pull requests for the YT-6 task (agent_issues 1000597) because qnfo-youtube-shorts declares [[containers]]. The change was rebuilt as a session pull request (5174, qnfo-youtube-shorts 0.3.0): it is merged and deployed (GET /health answers 0.3.0-retention) and it ran: the tick of 2026-10-28T21:00:42Z recorded youtube.retention_scope (status warn, scope-missing) and the tick event carries retention {rows 2, wrote 0, failure scope-missing}, so the read path executes and refuses honestly instead of writing a zero. The one remaining step is the owner consent for youtube.readonly and yt-analytics.readonly, carried by the IDENTITY-BOUND card yt-analytics-consent; agent_issues 1000597 stays open on a probe that reads the metric youtube_avg_view_duration_s.'
FROM agent_issues a
WHERE a.id = 1000599 AND a.status = 'open'
  AND EXISTS (SELECT 1 FROM cloud_ops_events e WHERE e.job = 'qnfo-youtube-shorts' AND e.kind = 'youtube.tick' AND instr(e.text, '"retention"') > 0)
  AND EXISTS (SELECT 1 FROM pragma_table_info('youtube_videos') WHERE name = 'avg_view_duration_s')
ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = 'closed', owner = excluded.owner, close_evidence = excluded.close_evidence;
UPDATE agent_issues SET close_channel = 'session:cluster-f-a' WHERE id = 1000599 AND status = 'closed' AND close_channel LIKE 'auto:triage-sync:cluster-f-a%';

-- 100166: the code-task for the in-account twin
UPDATE agent_issues SET description = description || char(10) || char(10) || 'CLUSTER-F-A 2026-10-28: binding-census@cf failed at every run from 16:40Z to 20:20Z on "census sees every worker" naming qnfo-workers (and qnfo-cf-one-dashboard until its retirement), while binding-census@gha and the public /fleet read all workers healthy. qnfo-workers is the repository-root stub that Workers Builds recreates on every push (modified_on moves with each merge); while it answers 410 with a retired marker qnfo-ops reports healthy null with retired true and skips the heartbeat merge by design (OPS-FLEET-RETIRED-1), and the journey counted every healthy null row as blind. The runner side (scripts/fleet_journeys.py) is fixed (PR 5176). The in-account twin is the line below in qnfo-fleet-control/worker.js: a row with retired true is not blind (add && x.retired !== true to the filter), with a case in the journeys suite.' || char(10) || 'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) || 'code-anchor: var blind = rows.filter(function(x) { return x.healthy === null || x.healthy === undefined; }).map(function(x) { return x.name; });'
WHERE id = 100166 AND instr(description, 'CLUSTER-F-A 2026-10-28') = 0;

